insert into public.legal_rule (rule_id, instrument, instrument_no, article, topic, summary_ar, conditions_ar, exceptions_ar, deadline_ar, required_docs_ar, source_url, source_kind, enforcement, review_status, original_text_loaded, last_checked_on, workflow) values
('WASTE-80-2018','قانون','80/2018 (10/10/2018)','عام','قانون الإدارة المتكاملة للنفايات الصلبة','القانون الإطار لإدارة النفايات الصلبة. يعرّف «الإدارات المحلية» بأنها البلديات واتحادات البلديات وتجمّعاتها وتنظيمات اللامركزية الإدارية، ويوجب اعتماد اللامركزية في الإدارة (م.9 بحسب مقالات قانونية). المادة 28 فيه تحدد مصادر التمويل وقد عُدّلت بالقانون 38/2026.',null,null,null,null,'http://www.legallaw.ul.edu.lb/LawView.aspx?LawID=278572','secondary','INFORMATION','pending_review',false,'2026-11-26','waste'),
('WASTE-80-28','قانون','80/2018','28','مصادر تمويل إدارة النفايات (الأصل قبل التعديل)','تنص المادة 28 على مصادر تمويل الاستراتيجية الوطنية والبرامج المحلية، أولها اعتمادات الموازنة العامة للهيئة الوطنية لإدارة النفايات الصلبة. أضاف القانون 38/2026 بندين: رسم خدمة جمع النفايات للإدارات المحلية، وضريبة/رسم بيئي على قيمة المنتج يعود للخزينة. النص المعدَّل الكامل لم يُحمَّل بعد.',null,null,null,null,'http://www.legallaw.ul.edu.lb/LawView.aspx?LawID=278572','secondary','INFORMATION','pending_review',false,'2026-11-26','waste'),
('WASTE-38-2026','قانون','38/2026 (5/1/2026)','تعديل م.28 من 80/2018','قانون استرداد الكلفة: رسم خدمة جمع النفايات','عدّل المادة 28 من القانون 80/2018. بحسب ما نُشر: يُستحدث رسم لخدمة جمع النفايات المنزلية ونقلها تستوفيه الإدارات المحلية (البلديات) ضمن نطاقها من الوحدات السكنية والمؤسسات العامة والخاصة، وتُحتسب بحسب نوع المؤسسة واستعمال المبنى والمساحة وعدد الشاغلين. يُضاف إلى ذلك رسم بيئي على قيمة منتجات مستوردة يعود للخزينة. لا يحدد المصدر الذي اطلعنا عليه من يضع قيمة الرسم البلدي ولا آلية الجباية: يلزم التحقق من النص الرسمي والمرسوم 3740 قبل أي قرار بلدي.','معايير الاحتساب: نوع المؤسسة، استعمال المبنى، المساحة، عدد الشاغلين (بحسب مقال منشور)',null,null,'نص القانون المنشور في الجريدة الرسمية','https://www.saidaonline.com/322016','secondary','WARNING','pending_review',false,'2026-11-26','waste'),
('WASTE-CC-2-2026','قرار المجلس الدستوري','2/2026 (26/2/2026)','—','ردّ الطعن بالقانون 38/2026 مع تحفظ تفسيري','ردّ المجلس الدستوري الطعن بالقانون 38/2026 واعتبره غير مخالف للدستور، مع تحفظ تفسيري يمنع تحويل صلاحية تعديل الرسوم إلى تفويض بتعديل القانون نفسه (بحسب «المفكرة القانونية»). أي أن تطبيق القانون يجب أن يلتزم بهذا التحفظ.',null,null,null,null,'https://legal-agenda.com/%D9%87%D9%84-%D9%8A%D8%B9%D9%8A%D8%AF-%D8%A7%D9%84%D9%86%D9%82%D8%A7%D8%B4-%D8%AD%D9%88%D9%84-%D8%A5%D8%AF%D8%A7%D8%B1%D8%A9-%D8%A7%D9%84%D9%86%D9%81%D8%A7%D9%8A%D8%A7%D8%AA-%D8%A7%D9%84%D8%B5%D9%84/','secondary','INFORMATION','pending_review',false,'2026-11-26','waste'),
('WASTE-DEC-3214','مرسوم','3214/2026 (15/6/2026)','—','مرسوم رفع الرسوم البيئية على المنتجات (معلَّق)','صدر في 15/6/2026 ويرفع الرسوم البيئية على نحو 98 فئة من المنتجات المستوردة. علّق مجلس الوزراء العمل به في 29/6/2026 وأحاله لإعادة الدرس، مؤكدًا ضرورة تطبيق القانون 38/2026. لا يخص الرسم البلدي.',null,null,null,null,'https://www.almodon.com/economy/2026/06/29/%D8%A7%D9%84%D8%AD%D9%83%D9%88%D9%85%D8%A9-%D8%AA%D8%AA%D8%B1%D8%A7%D8%AC%D8%B9-%D8%B9%D9%86-%D8%A7%D9%84%D8%B1%D8%B3%D9%88%D9%85-%D8%AA%D8%B9%D9%84%D9%8A%D9%82-%D8%A7%D9%84%D9%85%D8%B1%D8%B3%D9%88%D9%85-%D8%AA%D8%AD%D8%AA-%D8%B6%D8%BA%D8%B7-%D8%A7%D9%84%D8%A7%D8%B9%D8%AA%D8%B1%D8%A7%D8%B6%D8%A7%D8%AA','secondary','INFORMATION','pending_review',false,'2026-11-26','waste'),
('WASTE-DEC-3740','مرسوم تطبيقي','3740/2026 (24/8/2026)','—','المرسوم التطبيقي للمادة 28','المرسوم التطبيقي رقم 3740 تاريخ 24/8/2026 لتطبيق المادة 28 (بحسب الأخبار، ونُشر في الجريدة الرسمية). يلزم تحميل نصه ومعرفة ما يحدده للبلديات: قيمة الرسم أو إطاره، وآلية الجباية، والجهة المخوّلة تحديده.',null,null,null,'نص المرسوم من الجريدة الرسمية','https://lebnewsonline.com/?p=485573','secondary','WARNING','pending_review',false,'2026-11-26','waste'),
('WASTE-DEC-3754','مرسوم','3754/2026 (آب 2026، التاريخ غير مؤكد)','—','تعديل مرسوم الرسوم البيئية على المنتجات','بحسب الأخبار (27/8/2026): يعدّل مرسوم الرسوم البيئية، فيلغي الزيادة المضافة على فئات الجدول (1) المرفق بالقانون 38/2026 ويعيدها لمستوياتها، ويحدد نسب الجدول (2) على مجموعات سلع بحسب فصول التعرفة الجمركية. يخص الجمارك والخزينة لا الرسم البلدي. تاريخ الصدور ونفاذه غير مؤكدين.',null,null,null,null,'https://www.lbcgroup.tv/news/lebanon/954622/%D8%AA%D8%B9%D8%AF%D9%8A%D9%84-%D8%A7%D9%84%D8%B1%D8%B3%D9%88%D9%85-%D8%A7%D9%84%D8%A8%D9%8A%D8%A6%D9%8A%D8%A9-%D8%B9%D9%84%D9%89-%D8%A7%D9%84%D9%85%D9%88%D8%A7%D8%AF-%D8%A7%D9%84%D9%85%D9%86%D8%AA%D8%AC%D8%A9-%D9%84%D9%84%D9%86%D9%81%D8%A7%D9%8A%D8%A7%D8%AA/ar','secondary','INFORMATION','pending_review',false,'2026-11-26','waste'),
('WASTE-CAB-7-2026','قرار مجلس الوزراء','7 (جلسة 10/9/2026)','—','تلزيم جمع النفايات والكنس بعد 2026','قرار يخص تلزيم أعمال جمع النفايات وكنس الشوارع؛ بحسب «المدن» تنتهي العقود القائمة في بيروت وأقضية المتن وكسروان وبعبدا وعاليه والشوف في 31/12/2026. يهم البلديات التي ستتسلّم الجمع والكنس. يلزم تحميل نص القرار.',null,null,'31/12/2026 (نهاية العقود القائمة)',null,'https://www.almodon.com/society/2026/09/28/%D8%A5%D8%B4%D9%83%D8%A7%D9%84%D9%8A%D8%A9-%D8%A7%D9%84%D8%AC%D9%85%D8%B9-%D9%88%D8%A7%D9%84%D8%B7%D9%85%D8%B1-%D9%88%D8%A7%D9%84%D8%AA%D9%85%D9%88%D9%8A%D9%84-%D9%83%D9%8A-%D9%84%D8%A7-%D9%86%D8%BA%D8%B1%D9%82-%D9%85%D8%AC%D8%AF%D8%AF%D8%A7-%D8%A8%D8%A7%D9%84%D9%86%D9%81%D8%A7%D9%8A%D8%A7%D8%AA','secondary','INFORMATION','pending_review',false,'2026-11-26','waste'),
('WASTE-STRATEGY-2026','قرار مجلس الوزراء','28/2026 (30/1/2026)','—','الاستراتيجية المحدّثة وتوزيع المهام','بحسب المنشور: وفق الاستراتيجية المحدّثة تتولى البلديات الجمع والنقل والفرز من المصدر، وتتولى الهيئة الوطنية لإدارة النفايات الصلبة المعالجة والتدوير والطمر الصحي. رقم القرار وتاريخه لم نتحقق منهما من نص رسمي.',null,null,null,null,'https://www.saidaonline.com/322016','secondary','INFORMATION','pending_review',false,'2026-11-26','waste'),
('WASTE-PROPOSAL-80','اقتراح قانون (غير نافذ)','تعديل بعض مواد 80/2018','—','اقتراح تعديل القانون 80/2018','اقتراح قانون مدرج على جدول جلسة اللجان المشتركة في 14/10/2026 يرمي لتعديل بعض مواد القانون 80/2018. هو اقتراح فقط وليس قانونًا نافذًا؛ لا يُبنى عليه أي قرار بلدي.',null,null,null,null,'https://legal-agenda.com/%D9%87%D9%84-%D9%8A%D8%B9%D9%8A%D8%AF-%D8%A7%D9%84%D9%86%D9%82%D8%A7%D8%B4-%D8%AD%D9%88%D9%84-%D8%A5%D8%AF%D8%A7%D8%B1%D8%A9-%D8%A7%D9%84%D9%86%D9%81%D8%A7%D9%8A%D8%A7%D8%AA-%D8%A7%D9%84%D8%B5%D9%84/','secondary','INFORMATION','pending_review',false,'2026-11-26','waste')
